12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // list_sessions runs off the lock: a history request must not queue behind a streaming answer.
48	    if (isListSessionsFrame(rawMessage)) {
49	      return answerListSessions(ws, session, sessionStore, validation);
50	    }
51	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
52	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
53	  };
54	}
55	
56	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
57	async function answerInTurn(
58	  ws: WebSocket,
59	  session: ChatSession,
60	  orchestrator: ChatOrchestrator,
61	  validation: ValidationResult,
62	  signal: AbortSignal | undefined
63	): Promise<void> {
64	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
65	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
66	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
67	    return;
68	  }
69	  const startedAt = Date.now();
70	  try {
71	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
72	  } finally {
73	    endTurn(ws, session, signal, startedAt);
74	  }
75	}
76	
77	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
78	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
79	  if (signal?.aborted) {
80	    log.info('message', 'turn abandoned: its socket closed', {
81	      sessionId: session.sessionId,
82	      elapsedMs: Date.now() - startedAt,
83	    });
84	    return;
85	  }
86	  sendStreamEnd(ws);
87	}
88	
89	async function answerUserMessage(
90	  ws: WebSocket,
91	  session: ChatSession,
92	  orchestrator: ChatOrchestrator,
93	  validation: ValidationResult,
94	  signal: AbortSignal | undefined
95	): Promise<void> {
96	  const message = validation.valid ? validation.data : undefined;
97	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
98	  answerFrame(ws, validation);
99	}
100	
101	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
102	  if (!validation.valid) {
103	    log.warn('message', 'validation failed', {error: validation.error});
104	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
105	    return;
106	  }
107	
108	  const message = validation.data;
109	  if (message.type === 'ping') handlePing(ws, message.timestamp);
110	}
111	
112	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
113	function isUserMessageFrame(rawMessage: unknown): boolean {
114	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
115	}
116	
117	function isListSessionsFrame(rawMessage: unknown): boolean {
118	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_sessions';
119	}
120	
121	async function answerListSessions(
122	  ws: WebSocket,
123	  session: ChatSession,
124	  sessionStore: SessionStore | undefined,
125	  validation: ValidationResult
126	): Promise<void> {
127	  if (!validation.valid) {
128	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
129	    return;
130	  }
131	  const message = validation.data;
132	  if (message.type !== 'list_sessions') return;
133	
134	  if (!sessionStore?.listFor) {
135	    sendJson(ws, {type: 'session_list', sessions: []});
136	    return;
137	  }
138	
139	  const {limit, before} = message;
140	  try {
141	    const summaries = await sessionStore.listFor(session.userId, {limit, before});
142	    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryWire)});
143	  } catch (err) {
144	    const errorMsg = err instanceof Error ? err.message : 'Unknown error';
145	    log.error('ws', 'conversation list failed', {userId: session.userId, error: errorMsg});
146	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
147	  }
148	}
149	
150	function toSummaryWire(s: SessionSummary): {
151	  sessionId: string;
152	  createdAt: string;
153	  updatedAt: string;
154	  entryCount: number;
155	} {
156	  return {
157	    sessionId: s.sessionId,
158	    createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
159	    updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
160	    entryCount: s.entryCount,
161	  };
162	}
163	
164	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
165	  try {
166	    await action();
167	  } catch (error) {
168	    const message = error instanceof Error ? error.message : 'Unknown error';
169	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
170	    log.error('message', 'handling error', {error: message, code});
171	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
172	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
173	      return;
174	    }
175	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
176	  }
177	}
178	
179	async function handleUserMessage(
180	  ws: WebSocket,
181	  session: ChatSession,
182	  orchestrator: ChatOrchestrator,
183	  content: string,
184	  signal: AbortSignal | undefined
185	): Promise<void> {
186	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
187	
188	  const userEntry = createUserEntry(content);
189	  const userIndex = appendEntry(session, userEntry);
190	  sendUpsert(ws, userIndex, userEntry);
191	
192	  const parser = new ThinkingTagParser();
193	  const state: StreamState = {
194	    thinkingIndex: null,
195	    assistantIndex: null,
196	    suppressOutput: false,
197	    sentAssistantIndices: [],
198	  };
199	
200	  let textChunkCount = 0;
201	
202	  try {
203	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
204	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
205	      if (signal?.aborted) break;
206	      textChunkCount = logChunk(chunk, textChunkCount);
207	      processChunk(ws, session, state, parser, chunk);
208	    }
209	  } finally {
210	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
211	    flushHeldText(ws, session, state, parser);
212	    closeCutOff(ws, session, state, 'thinkingIndex');
213	    closeCutOff(ws, session, state, 'assistantIndex');
214	  }
215	
216	  if (textChunkCount > 0) {
217	    log.debug('stream', `received ${textChunkCount} text chunks`);
218	  }
219	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
220	}
221	
222	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
223	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
224	  if (chunk.type === 'text') return textChunkCount + 1;
225	
226	  if (textChunkCount > 0) {
227	    log.debug('stream', `received ${textChunkCount} text chunks`);
228	  }
229	
230	  if (chunk.type === 'tool_result') {
231	    log.debug('stream', 'tool_result chunk', {
232	      messageCount: chunk.clientMessages.length,
233	      types: chunk.clientMessages.map(m => m.type),
234	    });
235	    return 0;
236	  }
237	
238	  log.debug('stream', 'chunk', {type: chunk.type});
239	  return 0;
240	}
241	
242	function processChunk(
243	  ws: WebSocket,
244	  session: ChatSession,
245	  state: StreamState,
246	  parser: ThinkingTagParser,
247	  chunk: MessageChunk
248	): void {
249	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
250	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
251	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
252	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
253	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
254	}
255	
256	function processTextChunk(
257	  ws: WebSocket,
258	  session: ChatSession,
259	  state: StreamState,
260	  parser: ThinkingTagParser,
261	  text: string
262	): void {
263	  const segments = parser.push(text);
264	  for (const segment of segments) {
265	    handleTextSegment(ws, session, state, segment);
266	  }
267	}
268	
269	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
270	  if (segment.type === 'thinking') {
271	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
272	    return;
273	  }
274	  commitAndClear(ws, session, state, 'thinkingIndex');
275	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
276	}
277	
278	function streamSegment(
279	  ws: WebSocket,
280	  session: ChatSession,
281	  state: StreamState,
282	  key: StateIndexKey,
283	  createEntry: EntryFactory,
284	  content: string
285	): void {
286	  const isNew = initSegment(session, state, key, createEntry);
287	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
288	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
289	  appendDelta(session, state[key]!, content);
290	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
291	}
292	
293	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
294	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
295	  markSuppressed(session, index);
296	  sendSkip(ws, index);
297	}
298	
299	function markSuppressed(session: ChatSession, index: number): void {
300	  const entry = session.entries[index];
301	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
302	}
303	
304	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
305	  if (state[key] !== null) return false;
306	  state[key] = appendEntry(session, createEntry());
307	  return true;
308	}
309	
310	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
311	  const index = state[key];
312	  if (index === null) return;
313	
314	  commitEntry(session, index);
315	  state[key] = null;
316	
317	  // Only what the client received can be retracted, and only assistant entries.
318	  if (state.suppressOutput) return;
319	
320	  sendCommit(ws, index);
321	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
322	}
323	
324	function processToolUseChunk(
325	  ws: WebSocket,
326	  session: ChatSession,
327	  toolCall: {name: string; input: Record<string, unknown>}
328	): void {
329	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
330	  const toolIndex = appendEntry(session, toolEntry);
331	  sendUpsert(ws, toolIndex, toolEntry);
332	}
333	
334	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
335	  for (const msg of clientMessages) {
336	    log.debug('stream', 'forwarding client message to frontend', {
337	      type: msg.type,
338	      index: 'index' in msg ? msg.index : undefined,
339	    });
340	    sendJson(ws, msg);
341	  }
342	}
343	
344	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
345	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
346	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
347	  commitOpenEntries(ws, session, state);
348	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
349	
350	  for (const idx of state.sentAssistantIndices) {
351	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
352	    markSuppressed(session, idx);
353	  }
354	
355	  state.sentAssistantIndices = [];
356	  state.suppressOutput = true;
357	}
358	
359	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
360	  flushHeldText(ws, session, state, parser);
361	  commitOpenEntries(ws, session, state);
362	}
363	
364	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
365	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
366	  for (const segment of parser.flush()) {
367	    handleTextSegment(ws, session, state, segment);
368	  }
369	}
370	
371	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
372	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
373	  const index = state[key];
374	  if (index === null) return;
375	  markTruncated(session, index);
376	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
377	  commitAndClear(ws, session, state, key);
378	}
379	
380	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
381	  commitAndClear(ws, session, state, 'thinkingIndex');
382	  commitAndClear(ws, session, state, 'assistantIndex');
383	}
384	
385	function handlePing(ws: WebSocket, timestamp: number): void {
386	  ws.send(JSON.stringify({type: 'pong', timestamp}));
387	}
388

